	got[0].Effect = EffectDeny
	got[0].Subject = "nobody"
	if d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")); !d.Allowed {
		t.Fatalf("published content changed by query-result mutation: %+v", d)
	}
}

func TestReviewPinsHistoricalVersion(t *testing.T) {
	s := NewStore()
	v1, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	if err != nil {
		t.Fatal(err)
	}
	req := request("acme", "u1", "r1", "org/a", "read")
	before := s.Review("acme", v1, req)
	if !before.Allowed || before.Version != v1 {
		t.Fatalf("review before changes: %+v", before)
	}
	// Later publish and rollback must not change the review of v1.
	if _, err := s.Publish("acme", v1, nil); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Rollback("acme", 2, 2); err != nil {
		t.Fatal(err)
	}
	after := s.Review("acme", v1, req)
	if !reflect.DeepEqual(before, after) {
		t.Fatalf("review changed after later publishes: before=%+v after=%+v", before, after)
	}
	// A version that does not exist denies with a reason, no silent fallback.
	d := s.Review("acme", 99, req)
	if d.Allowed || d.Version != 0 {
		t.Fatalf("review of missing version: %+v", d)
	}
	if d := s.Review("acme", 0, req); d.Allowed {
		t.Fatalf("review of version 0 must deny: %+v", d)
	}
}

func TestOrganizationsAreIndependent(t *testing.T) {
	s := NewStore()
	// Same subject, resource and policy identifiers in two organizations.
	if _, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Publish("globex", 0, nil); err != nil {
		t.Fatal(err)
	}
	if d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")); !d.Allowed {
		t.Fatalf("acme decision: %+v", d)
	}
	if d := s.Decide("globex", request("globex", "u1", "r1", "org/a", "read")); d.Allowed {
		t.Fatalf("globex decision leaked acme policy: %+v", d)
	}
	// Versions advance independently.
	v, err := s.Publish("globex", 1, nil)
	if err != nil || v != 2 {
		t.Fatalf("globex second publish = %d, %v; want 2, nil", v, err)
	}
	if got := s.CurrentVersion("acme"); got != 1 {
		t.Fatalf("acme current = %d, want 1", got)
	}
}

// This file implements the organization-scoped audit chain. Every successful
// policy publish or rollback, and every Decide called with a non-empty
// decision organization, leaves an immutable record in that organization.
//
// Records carry an organization-local sequence starting at 1 and a SHA-256
// fingerprint that chains each record to the previous one. The genesis
// fingerprint binds the organization name, so records from another
// organization can never validate as part of this chain even when the
// sequence numbers and identifiers coincide.
package darksafe

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
)

// Audit record categories.
const (
	// AuditPolicyChange is a successful publish or rollback.
	AuditPolicyChange = "policy_change"
	// AuditDecision is one Decide evaluation.
	AuditDecision = "decision"
)

// Sentinel errors for the audit entry points. Callers distinguish them
// with errors.Is; every one leaves state unchanged.
var (
	// ErrInvalidPage means a page size or range argument was invalid.
	ErrInvalidPage = errors.New("darksafe: invalid audit page")
	// ErrInvalidRange means the upper bound is beyond what exists, the
	// range is inverted, or a supplied fingerprint does not match.
	ErrInvalidRange = errors.New("darksafe: invalid audit range")
	// ErrAuditNotFound means no record exists at the requested sequence.
	ErrAuditNotFound = errors.New("darksafe: audit record not found")
	// ErrAuditNotADecision means the record at the sequence is not a
	// decision record and therefore cannot be rechecked.
	ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
)

// PolicyChange captures a successful publish or rollback.
type PolicyChange struct {
	// Version is the newly created policy version.
	Version int
	// Policies is the full policy set of the new version.
	Policies []Policy
	// SourceVersion is the version copied by a rollback, and 0 for an
	// ordinary publish.
	SourceVersion int
	// RolledBack reports whether the change was produced by Rollback.
	RolledBack bool
}

// DecisionRecord captures one Decide call: the full request and the
// decision actually returned.
type DecisionRecord struct {
	Request  OrgRequest
	Decision Decision
}

// AuditRecord is one immutable entry in an organization's audit chain.
type AuditRecord struct {
	Org      string
	Seq      int // organization-local, starting at 1 and gapless
	Kind     string
	Change   *PolicyChange   // present when Kind == AuditPolicyChange
	Decision *DecisionRecord // present when Kind == AuditDecision

	// PrevFingerprint is the fingerprint of the preceding record, or the
	// genesis fingerprint for the first record.
	PrevFingerprint string
	// Fingerprint binds this record's full content to its predecessor.
	Fingerprint string
}

// rawEnvelopePrefix opens every raw-byte canonical encoding. It never
// coincides with the start of a JSON envelope (always '{'), so
// fingerprints from the two encodings live in collision-free spaces.
const rawEnvelopePrefix = "darksafe-audit-raw-v1\x00"

// fingerprintTag delimits one field or nested value within the canonical
// binary encoding. Distinct tags keep two payloads that merely share
// adjacent bytes apart (e.g. ["ab",""] vs ["a","b"]).
type fingerprintTag byte

const (
	tagEnvelope fingerprintTag = iota + 1
	tagSeq
	tagString
	tagStringList
	tagBool
	tagPolicy
	tagPolicyList
	tagChange
	tagSubject
	tagResource
	tagDecision
	tagDecisionRecord
)

// fingerprintEncoder builds the canonical byte representation of an
// envelope. Unlike encoding/json it writes string contents byte-for-byte
// with an explicit length prefix, so strings carrying invalid UTF-8 stay
// distinguishable: encoding/json renders both a raw 0xFF byte and a raw
// 0xFE byte as the U+FFFD replacement rune, collapsing genuinely
// different content onto identical fingerprints.
type fingerprintEncoder struct {
	buf []byte
}

func (e *fingerprintEncoder) tag(t fingerprintTag) {
	e.buf = append(e.buf, byte(t))
}

func (e *fingerprintEncoder) int64Tag(t fingerprintTag, v int64) {
	e.tag(t)
	var b [8]byte
	binary.BigEndian.PutUint64(b[:], uint64(v))
	e.buf = append(e.buf, b[:]...)
}

func (e *fingerprintEncoder) boolTag(t fingerprintTag, v bool) {
	e.tag(t)
	if v {
		e.buf = append(e.buf, 1)
	} else {
		e.buf = append(e.buf, 0)
	}
}

// rawString tags and writes a string from its exact memory bytes. No
// validation, replacement or normalization is ever performed: an invalid
// UTF-8 byte reaches the hash unchanged.
func (e *fingerprintEncoder) rawString(s string) {
	e.tag(tagString)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(s)))
	e.buf = append(e.buf, b[:]...)
	e.buf = append(e.buf, s...)
}

// put appends one raw framing byte. It is the fingerprint sink's side of the
// shared list shape: the list presence marker goes into the canonical bytes
// verbatim.
func (e *fingerprintEncoder) put(b byte) {
	e.buf = append(e.buf, b)
}

// listCount writes a list element count as a big-endian uint32. The raw
// canonical encoding has no length ceiling beyond the hash input, so unlike
// the archive sink the count is written unconditionally; only the list shape
// (nil marker, presence marker, count then one item per element) is shared.
func (e *fingerprintEncoder) listCount(n int) {
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(n))
	e.buf = append(e.buf, b[:]...)
}

// stringList preserves nil-vs-empty explicitly: in the JSON envelope a
// nil slice is "null" and a non-nil empty slice is "[]", so the raw
// encoding must keep the two shapes apart as well. The list's own kind tag
// leads, then the shared list shape carries the presence marker, count and
// elements under it.
func (e *fingerprintEncoder) stringList(items []string) {
	e.tag(tagStringList)
	writeListShape(e, items, e.rawString)
}

func (e *fingerprintEncoder) policy(p Policy) {
	e.tag(tagPolicy)
	// Field order, the Recursive boolean's position, and ResourceID being
	// appended only when set all come from the single policy field table, so
	// the fingerprint and the archive enumerate fields in exactly one place.
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString:
			e.rawString(f.getString(p))
		case policyFieldOptionalString:
			// ResourceID participates only when set, pairing with its
			// omitempty JSON tag, so the legacy fingerprint bytes are
			// unchanged for resource-unrestricted policies.
			if v := f.getString(p); v != "" {
				e.rawString(v)
			}
		case policyFieldBool:
			e.boolTag(tagBool, f.getBool(p))
		}
	}
}

// policyList frames the full policy set with the shared list shape, led by
// the policy-list tag so a policy set can never collide with a string list
// whose concatenated bytes happen to match.
func (e *fingerprintEncoder) policyList(policies []Policy) {
	e.tag(tagPolicyList)
	writeListShape(e, policies, e.policy)
}

func (e *fingerprintEncoder) change(c *PolicyChange) {
	e.tag(tagChange)
	// A nil pointer is encoded as tagChange alone; a present value's
	// fields follow immediately.
	if c == nil {
		return
	}
	// Field order comes from the single policy-change field table, so the
	// fingerprint, the UTF-8 decision, the archive and the detaching copy
	// enumerate fields in exactly one place. No change field is skipped.
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(c)))
		case changeFieldPolicyList:
			e.policyList(f.getPolicies(c))
		case changeFieldBool:
			e.boolTag(tagBool, f.getBool(c))
		}
	}
}

func (e *fingerprintEncoder) decisionRecord(d *DecisionRecord) {
	e.tag(tagDecisionRecord)
	if d == nil {
		return
	}
	// Field order and the subject/resource/decision group markers all come
	// from the single decision field table, so the fingerprint, the UTF-8
	// decision and the archive enumerate fields in exactly one place. No
	// request or decision field is skipped.
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.groupTag != 0 {
			e.tag(f.groupTag)
		}
		switch f.kind {
		case decisionFieldString:
			e.rawString(f.getString(d))
		case decisionFieldStringList:
			e.stringList(f.getList(d))
		case decisionFieldBool:
			e.boolTag(tagBool, f.getBool(d))
		case decisionFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(d)))
		}
	}
}

// encodeCanonical returns the raw bytes fingerprinted for a record whose
// strings include invalid UTF-8. Every string the record carries reaches
// the output byte-for-byte, at whatever nesting depth or list position it
// occupies. The prefix separates this encoding space from JSON
// fingerprints. The outer fields come from the single record field table,
// so this encoding enumerates exactly the envelope members the JSON
// encoding and the valid-UTF-8 scan see, in the same order.
func encodeCanonical(r *AuditRecord) []byte {
	e := &fingerprintEncoder{buf: []byte(rawEnvelopePrefix)}
	e.tag(tagEnvelope)
	for i := range recordFields {
		f := &recordFields[i]
		if f.jsonKey == "" {
			// The record's own fingerprint is never an input to itself.
			continue
		}
		switch f.kind {
		case recordFieldString:
			e.rawString(f.getString(r))
		case recordFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(r)))
		case recordFieldChange:
			e.change(f.getChange(r))
		case recordFieldDecision:
			e.decisionRecord(f.getDecision(r))
		}
	}
	return e.buf
}

// genesisFingerprint derives the chain root from the organization name,
// keeping equal identifiers in different organizations independent.
func genesisFingerprint(org string) string {
	sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
	return hex.EncodeToString(sum[:])
}

// encodeJSONEnvelope renders the fingerprint envelope of a record whose
// strings are all valid UTF-8 as the exact byte sequence the historical
// encoding/json envelope struct produced: the envelope members in the
// single record field table's order, every string, integer and payload
// encoded by encoding/json itself, and the two payload members dropped
// when absent exactly as their historical omitempty tags did. Walking the
// table keeps this object in lockstep with the raw canonical encoding, the
// valid-UTF-8 scan and the archive framing by construction.
func encodeJSONEnvelope(r *AuditRecord) []byte {
	var buf []byte
	buf = append(buf, '{')
	first := true
	for i := range recordFields {
		f := &recordFields[i]
		if f.jsonKey == "" {
			// The record's own fingerprint is never an input to itself.
			continue
		}
		var (
			value []byte
			err   error
		)
		switch f.kind {
		case recordFieldString:
			value, err = json.Marshal(f.getString(r))
		case recordFieldInt:
			value, err = json.Marshal(f.getInt(r))
		case recordFieldChange:
			c := f.getChange(r)
			if c == nil {
				continue
			}
			value, err = json.Marshal(c)
		case recordFieldDecision:
			d := f.getDecision(r)
			if d == nil {
				continue
			}
			value, err = json.Marshal(d)
		}
		if err != nil {
			// All envelope values are plain, JSON-encodable values; a
			// failure here indicates a programming error, not user input.
			panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
		}
		if !first {
			buf = append(buf, ',')
		}
		first = false
		buf = append(buf, '"')
		buf = append(buf, f.jsonKey...)
		buf = append(buf, '"', ':')
		buf = append(buf, value...)
	}
	return append(buf, '}')
}

// fingerprintFor returns the fingerprint for a record. Records made
// exclusively of valid UTF-8 keep the historical JSON fingerprint, so old
// exports and checkpoints remain valid; records containing invalid bytes
// use the length-prefixed raw encoding that protects their exact bytes.
// Both families cover exactly the envelope members of the single record
// field table — never the record's own fingerprint.
func fingerprintFor(r *AuditRecord) string {
	if recordUsesRawBytes(r) {
		sum := sha256.Sum256(encodeCanonical(r))
		return hex.EncodeToString(sum[:])
	}
	sum := sha256.Sum256(encodeJSONEnvelope(r))
	return hex.EncodeToString(sum[:])
}

// clonePolicies returns a detached copy of a policy set.
func clonePolicies(in []Policy) []Policy {
	if in == nil {
		return nil
	}
	return append([]Policy(nil), in...)
}

// cloneChange returns a detached copy of a policy-change payload.
func cloneChange(c *PolicyChange) *PolicyChange {
	if c == nil {
		return nil
	}
	cp := *c
	// Detach every list the single policy-change field table carries; the
	// per-list nil-versus-empty handling stays exactly as clonePolicies
	// defines it.
	cloneChangeLists(&cp, c)
	return &cp
}

// cloneStrings returns a detached copy of a string slice while preserving
// its nil-versus-empty shape: a nil slice stays nil, and every non-nil
// slice, including a non-nil empty slice that still carries spare capacity,
// receives its own backing array. Copying only when len > 0 is not enough:
// a caller may submit make([]string, 0, 4), and aliasing that array into a
// stored record would let an append to one handed-out copy overwrite the
// first element of every other copy that shares it.
func cloneStrings(in []string) []string {
	if in == nil {
		return nil
	}
	return append([]string{}, in...)
}

// cloneDecision returns a detached copy of a decision payload.
func cloneDecision(d *DecisionRecord) *DecisionRecord {
	if d == nil {
		return nil
	}
	cp := *d
	// Detach every list the single decision field table carries, on non-nil
	// rather than on len > 0 so empty-but-capacious lists are independent
	// copies too; nil lists stay nil.
	cloneDecisionLists(&cp, d)
	return &cp
}

// cloneRecord returns a fully detached copy of a record.
func cloneRecord(r *AuditRecord) *AuditRecord {
	cp := *r
	cp.Change = cloneChange(r.Change)
	cp.Decision = cloneDecision(r.Decision)
	return &cp
}

// appendAuditLocked validates, fingerprints and stores one record. It runs
// under the store mutex and is the single place records are created.
func (st *orgState) appendAuditLocked(org, kind string, change *PolicyChange, decision *DecisionRecord) *AuditRecord {
	seq := len(st.audit) + 1
	prev := genesisFingerprint(org)
	if len(st.audit) > 0 {
		prev = st.audit[len(st.audit)-1].Fingerprint
	}
	// Store detached copies; later caller mutation must not reach the chain.
	rec := &AuditRecord{
		Org:             org,
		Seq:             seq,
		Kind:            kind,
		Change:          cloneChange(change),
		Decision:        cloneDecision(decision),
		PrevFingerprint: prev,
	}
	rec.Fingerprint = fingerprintFor(rec)
	st.audit = append(st.audit, rec)
	return cloneRecord(rec)
}

// auditHeadLocked returns the highest sequence in the chain and the
// fingerprint that covers it: (0, genesis) for an organization with no
// records.
func (st *orgState) auditHeadLocked(org string) (int, string) {
	if len(st.audit) == 0 {
		return 0, genesisFingerprint(org)
	}
	last := st.audit[len(st.audit)-1]
	return last.Seq, last.Fingerprint
}

// Checkpoint pins an audit query to an exact point in a chain.
type Checkpoint struct {
	Org         string
	EndSeq      int
	Fingerprint string
}

// AuditPage is one stable slice of an organization's audit chain.
type AuditPage struct {
	Org     string
	Records []AuditRecord
	// BeginSeq/EndSeq delimit the whole pinned range, not just this page.
	BeginSeq int
	EndSeq   int
	// Next is the first sequence of the following page, 0 when exhausted.
	Next int
	// Checkpoint is the pinned upper bound shared by every page.
	Checkpoint Checkpoint
}

// recordMatches reports whether a record survives the query filters. Every
// set filter is a conjunction: kind, subject and resource conditions must
// all hold. Empty filter values mean "not set".
func recordMatches(r *AuditRecord, kind, subjectID, resourceID string) bool {
	if kind != "" && r.Kind != kind {
		return false
	}
	if subjectID != "" {
		// A subject filter selects decision records of that subject only.
		if r.Kind != AuditDecision || r.Decision == nil ||
			r.Decision.Request.Subject.ID != subjectID {
			return false
		}
	}
	if resourceID != "" {
		// A resource filter selects decision records whose request named
		// exactly this resource. Policy-change records never match, even when
		// a published policy carries the identical ResourceID: the condition
		// reads the requested resource, not policy content. The comparison is
		// Go string equality over the stored raw bytes, so case, surrounding
		// and internal spaces, control bytes and invalid UTF-8 are all
		// significant, and no path or wildcard is interpreted.
		if r.Kind != AuditDecision || r.Decision == nil ||
			r.Decision.Request.Resource.ID != resourceID {
			return false
		}
	}
	return true
}

// optionalResourceCondition extracts the optional resource condition passed
// as the trailing variadic argument. An absent argument or an empty string
// means "no resource filter"; supplying more than one condition is a caller
// error rather than a silently picked value.
func optionalResourceCondition(conds []string) (string, error) {
	switch len(conds) {
	case 0:
		return "", nil
	case 1:
		return conds[0], nil
	default:
		return "", fmt.Errorf("%w: at most one resource condition may be set, got %d", ErrInvalidPage, len(conds))
	}
}

// AuditQuery pins the first page of an audit query. startSeq is the first
// sequence considered (1 from the beginning); endSeq <= 0 means "everything
// currently stored". The returned checkpoint must be passed to AuditPage
// for the following pages, so records appended after the first query never
// mix into later pages.
//
// kind and subjectID are the existing optional filters (empty means unset):
// kind selects a record category and subjectID selects one subject's
// decision records. The optional trailing resourceID adds a resource
// condition, empty or absent meaning unset: only decision records whose
// requested resource ID equals it byte-for-byte survive — case sensitive,
// spaces and control bytes significant, no path or wildcard interpretation,
// invalid UTF-8 kept as-is — and policy-change records never survive it,
// even when a published policy names the same resource ID. Every set
// condition applies together. A resource filter changes only which records
// are returned: paging, checkpoints and detached copies behave exactly as
// without it, and omitting it preserves the historical call and its results.
func (s *Store) AuditQuery(org string, startSeq, pageSize int, kind, subjectID string, resourceID ...string) (*AuditPage, error) {
	resource, err := optionalResourceCondition(resourceID)
	if err != nil {
		return nil, err
	}
	if org == "" {
		return nil, ErrMissingOrganization
	}
	if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
		return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
	}
	if pageSize <= 0 {
		return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
	}
	if startSeq < 1 {
		return nil, fmt.Errorf("%w: start sequence must be >= 1, got %d", ErrInvalidPage, startSeq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	end, fingerprint := st.auditHeadLocked(org)
	cp := Checkpoint{Org: org, EndSeq: end, Fingerprint: fingerprint}
	if end == 0 {
		// An organization with no records always yields the empty genesis
		// page, regardless of where the caller asked to begin.
		return &AuditPage{Org: org, BeginSeq: 1, EndSeq: 0, Checkpoint: cp}, nil
	}
	if startSeq > end {
		return nil, fmt.Errorf("%w: start sequence %d is beyond end sequence %d", ErrInvalidRange, startSeq, end)
	}
	return s.auditPageLocked(org, startSeq, end, fingerprint, pageSize, kind, subjectID, resource), nil
}

// AuditPage returns one page of a previously pinned query. nextSeq is the
// cursor from the previous page; when it is 0 the range is exhausted. The
// checkpoint is re-verified against the chain on every call.
//
// A root checkpoint (EndSeq 0 with the organization's genesis fingerprint)
// pins the empty range the organization had when it was issued by a first
// AuditQuery or AuditExport. That range is finished independently of what
// the store currently holds for the organization: never seen, only queried
// empty, or since appended to — the answer is identical. Both terminal
// cursors, 0 and the one-past-end cursor 1, return the empty end page with
// BeginSeq 1, EndSeq 0 and Next 0; a cursor above 1 is ErrInvalidRange.
// Appended records never enter the pinned range; only a fresh AuditQuery
// pins the new tail.
//
// The filters are the same as AuditQuery's and must agree with the pinned
// query: pass the same kind, subjectID and optional resourceID on every
// page. The resource condition is an exact raw-byte match over requested
// resource IDs and excludes policy-change records, exactly as on the first
// page; omitting it keeps the historical call and result shape.
func (s *Store) AuditPage(cp Checkpoint, nextSeq, pageSize int, kind, subjectID string, resourceID ...string) (*AuditPage, error) {
	resource, err := optionalResourceCondition(resourceID)
	if err != nil {
		return nil, err
	}
	if cp.Org == "" {
		return nil, ErrMissingOrganization
	}
	if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
		return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
	}
	if pageSize <= 0 {
		return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
	}
	if nextSeq < 0 {
		return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
	}
	if cp.EndSeq < 0 {
		return nil, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidRange, cp.EndSeq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	genesis := genesisFingerprint(cp.Org)
	if cp.EndSeq == 0 {
		// A root checkpoint pins the empty range the organization had when
		// it was issued. Read-only paging must never depend on whether this
		// store happens to have visited the organization since: the chain
		// state for a never-seen org, an org only queried empty, and an org
		// that later grew records all answer the same.
		if cp.Fingerprint != genesis {
			return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the root at sequence 0", ErrInvalidRange)
		}
		// Cursor 0 means exhausted; cursor 1 is the one-past-the-end end
		// page, exactly like EndSeq+1 on a non-empty range — it never
		// restarts the walk (which is impossible anyway: the pinned range
		// contains no records). A larger cursor claims positive records the
		// checkpoint says do not exist, whether or not the live chain now
		// has them.
		if nextSeq > 1 {
			return nil, fmt.Errorf("%w: next sequence %d beyond pinned empty range ending at 0", ErrInvalidRange, nextSeq)
		}
		return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: 0, Next: 0, Checkpoint: cp}, nil
	}
	st, ok := s.orgs[cp.Org]
	if !ok {
		// The checkpoint claims positive records in an organization this
		// store has never seen; it can never verify.
		return nil, fmt.Errorf("%w: checkpoint organization has no records", ErrInvalidRange)
	}
	head := len(st.audit)
	if cp.EndSeq > head {
		return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
	}
	wantFP := st.audit[cp.EndSeq-1].Fingerprint
	if cp.Fingerprint != wantFP {
		return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the chain at sequence %d", ErrInvalidRange, cp.EndSeq)
	}
	if nextSeq == 0 {
		return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
	}
	if nextSeq > cp.EndSeq+1 {
		return nil, fmt.Errorf("%w: next sequence %d beyond pinned range ending at %d", ErrInvalidRange, nextSeq, cp.EndSeq)
	}
	if nextSeq == cp.EndSeq+1 {
		return &AuditPage{Org: cp.Org, BeginSeq: nextSeq, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
	}
	return s.auditPageLocked(cp.Org, nextSeq, cp.EndSeq, wantFP, pageSize, kind, subjectID, resource), nil
}

// auditPageLocked scans forward collecting up to pageSize matching records
// and computes the next-page cursor. It does not stop at pageSize raw
// records: filtering happens within the pinned [start,end] window, so
// non-matching records between matches — including policy changes excluded
// by a resource condition — never consume page slots.
func (s *Store) auditPageLocked(org string, startSeq, endSeq int, endFP string, pageSize int, kind, subjectID, resourceID string) *AuditPage {
	st := s.orgs[org]
	// pageSize only bounds how many records this page returns; it must not
	// drive allocation. A caller may pass any positive value, including the
	// largest int, for a range holding a handful of records, so preallocate
	// no more than the window can actually contain.
	window := endSeq - startSeq + 1
	capHint := pageSize
	if window < capHint {
		capHint = window
	}
	out := make([]AuditRecord, 0, capHint)
	i := startSeq
	for ; i <= endSeq && len(out) < pageSize; i++ {
		r := st.audit[i-1]
		if recordMatches(r, kind, subjectID, resourceID) {
			out = append(out, *cloneRecord(r))
		}
	}
	next := 0
	if i <= endSeq {
		next = i
	}
	return &AuditPage{
		Org:        org,
		Records:    out,
		BeginSeq:   startSeq,
		EndSeq:     endSeq,
		Next:       next,
		Checkpoint: Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: endFP},
	}
}

// AuditExport returns detached copies of the complete records through
// endSeq, suitable for offline verification. endSeq <= 0 means everything
// currently stored. An organization with no records yields an empty slice
// together with its sequence-0 checkpoint.
func (s *Store) AuditExport(org string, endSeq int) (records []AuditRecord, cp Checkpoint, err error) {
	if org == "" {
		return nil, Checkpoint{}, ErrMissingOrganization
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	head := len(st.audit)
	if endSeq <= 0 {
		endSeq = head
	}
	if endSeq > head {
		return nil, Checkpoint{}, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, endSeq, head)
	}
	if endSeq < 0 {
		return nil, Checkpoint{}, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidPage, endSeq)
	}
	// The checkpoint fingerprints the final exported record, not the
	// possibly later current head.
	fingerprint := genesisFingerprint(org)
	if endSeq > 0 {
		fingerprint = st.audit[endSeq-1].Fingerprint
	}
	out := make([]AuditRecord, 0, endSeq)
	for i := 0; i < endSeq; i++ {
		out = append(out, *cloneRecord(st.audit[i]))
	}
	return out, Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: fingerprint}, nil
}

// VerifyAudit validates an exported record set entirely without a Store.
// The caller separately retains the organization, end sequence and
// fingerprint they expect. It rejects any modified field, missing middle or
// tail record, swapped order, and record spliced in from another
// organization. Empty or nil records validate exactly when the checkpoint
// is the organization's genesis (end sequence 0).
func VerifyAudit(org string, records []AuditRecord, cp Checkpoint) error {
	if org == "" {
		return ErrMissingOrganization
	}
	if cp.Org != "" && cp.Org != org {
		return fmt.Errorf("%w: checkpoint organization %q does not match %q", ErrInvalidRange, cp.Org, org)
	}
	genesis := genesisFingerprint(org)
	if len(records) == 0 {
		if cp.EndSeq != 0 || cp.Fingerprint != genesis {
			return fmt.Errorf("%w: empty records but checkpoint claims end sequence %d", ErrInvalidRange, cp.EndSeq)
		}
		return nil
	}
	if cp.EndSeq != len(records) {
		return fmt.Errorf("%w: have %d records, checkpoint ends at %d", ErrInvalidRange, len(records), cp.EndSeq)
	}
	prev := genesis
	for i, r := range records {
		wantSeq := i + 1
		if r.Org != org {
			return fmt.Errorf("%w: record %d belongs to organization %q", ErrInvalidRange, wantSeq, r.Org)
		}
		if r.Seq != wantSeq {
			return fmt.Errorf("%w: record %d has sequence %d", ErrInvalidRange, wantSeq, r.Seq)
		}
		if r.PrevFingerprint != prev {
			return fmt.Errorf("%w: record %d breaks the chain", ErrInvalidRange, wantSeq)
		}
		wantFP := fingerprintFor(&r)
		if r.Fingerprint != wantFP {
			return fmt.Errorf("%w: record %d fingerprint mismatch", ErrInvalidRange, wantSeq)
		}
		if r.Kind == AuditPolicyChange {
			if r.Change == nil || r.Decision != nil {
				return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
			}
		} else if r.Kind == AuditDecision {
			if r.Decision == nil || r.Change != nil {
				return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
			}
		} else {
			return fmt.Errorf("%w: record %d has unknown category %q", ErrInvalidRange, wantSeq, r.Kind)
		}
		prev = r.Fingerprint
	}
	last := records[len(records)-1]
	if last.Fingerprint != cp.Fingerprint {
		return fmt.Errorf("%w: checkpoint fingerprint does not match the final record", ErrInvalidRange)
	}
	return nil
}

// RecheckDecision re-evaluates the request stored in an organization's
// decision record against the policy version that decision actually used.
// Later publishes or rollbacks cannot alter the result. Non-decision
// records and missing sequences return distinguishable errors.
//
// The record and the version snapshot come exclusively from this
// organization's own live history; the version-zero and historical-policy
// judgment itself is shared with RecheckDecisionOffline in
// replayRecordedDecision.
func (s *Store) RecheckDecision(org string, seq int) (Decision, error) {
	if org == "" {
		return Decision{}, ErrMissingOrganization
	}
	if seq < 1 {
		return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st, ok := s.orgs[org]
	if !ok || seq > len(st.audit) {
		return Decision{}, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
	}
	rec := st.audit[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return Decision{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}
	req := rec.Decision.Request
	version := rec.Decision.Decision.Version
	resolve := func(version int) versionPolicies {
		src, ok := st.versions[version]
		if !ok {
			// A decision's version is immutable and never deleted; its
			// absence indicates store tampering rather than normal
			// operation.
			return versionPolicies{status: replayVersionAbsent}
		}
		// Live snapshots are immutable; detach anyway so the returned
		// decision can never share storage with the store.
		return versionPolicies{policies: append([]Policy(nil), src...)}
	}
	d, status := replayRecordedDecision(org, req, version, resolve)
	if status == replayVersionAbsent {
		return Decision{}, fmt.Errorf("%w: decision used version %d, which no longer exists", ErrVersionNotFound, version)
	}
	return d, nil
}

// This file is the business regression guard for scope-name isolation in
// organization-level access decisions. Only an actual slash ('/', one byte
// 0x2F) is a hierarchy separator: every other byte in a scope segment —
// Chinese text, spaces, percent-encoded-looking text, even bytes that are
// not valid UTF-8 — is ordinary segment name content. Two requests that
// agree in organization, enabled subject, action and resource id and differ
// ONLY in the resource scope must therefore be decided by their scope's
// original bytes. No case folding, trimming, UTF-8 replacement, percent
// decoding or string-prefix reading may move an allow or a deny from one
// scope name onto a look-alike.
//
// The guarded rules, all already implemented by scopeMatches, validateScope
// and evaluate in org.go:
//
//   - An exact (non-recursive) policy matches its scope byte for byte and
//     nothing else. After one read allow is published, the same-named scope
//     is allowed by it alone; a differently cased name, a name with an extra
//     space, and a name that only LOOKS identical because a lone 0xFF, a lone
//     0xFE and a genuine U+FFFD display alike cannot borrow the allow. With
//     no other matching allow the answer is the default denial
//     "no matching allow policy", the hit list is empty, and the version is
//     still the published version that was evaluated.
//   - When each look-alike name carries its own policy, a request hits only
//     the policy bearing its own name; another name's deny never enters its
//     hit list or verdict. The single byte 0xFF, the single byte 0xFE and a
//     real U+FFFD rune stay three distinct scope names.
//   - A recursive policy keeps the exact same name comparison and additionally
//     covers true descendants: scopes equal to its raw name, or equal to its
//     raw name plus a slash plus more segments. A recursive allow on "org/a"
//     reaches "org/a/账本" but never "org/ab/账本"; the literal segment text
//     "%2F" is not a slash, so "org/a%2F账本" is a sibling, not a descendant.
//     Parents whose own name contains spaces or invalid UTF-8 bytes cover only
//     descendants formed by appending a slash to that parent's RAW name.
//   - Recursive denies obey the identical boundary: a deny that really matches
//     still overrides an allow ("matched deny policy", both identifiers kept in
//     ascending order, at the evaluated version), while a deny that misses the
//     requested scope name cannot affect another scope's access.
//   - A request scope containing consecutive slashes is rejected before any
//     policy is evaluated — never silently tidied and then matched. The
//     explanation is an explicit invalid-scope reason, version 0 and an empty
//     hit list, even when a published allow would cover the tidied path.
//
// All requests below are envelope-valid apart from the deliberately invalid
// scopes: the three organizations agree and the subject is enabled with its
// id, the resource id and the action present, so every outcome is genuinely
// produced by scope matching or the scope legality check, not by another
// envelope rule. The audit half pins that every explanation — allow, policy
// deny and default deny — survives the chain, historical review and offline
// review with its reason, hit identifiers and actual version intact.
package darksafe

import (
	"bytes"
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

// Shared fixture: one organization, one enabled subject, one resource id and
// one action. Requests differ only in the resource scope.
const (
	scopeNameOrg        = "acme"
	scopeNameSubjectID  = "svc-ledger-reader"
	scopeNameResourceID = "ledger-2026"
	scopeNameAction     = "read"
)

// scopeRequest builds an envelope-valid organization request carrying the
// given resource scope. Subject and resource organizations agree with the
// decision organization and the subject is enabled.
func scopeRequest(scope string) OrgRequest {
	return OrgRequest{
		SubjectOrg:  scopeNameOrg,
		ResourceOrg: scopeNameOrg,
		Subject:     Subject{ID: scopeNameSubjectID, Kind: "service"}, // enabled
		Resource:    Resource{ID: scopeNameResourceID, Scope: scope},
		Action:      scopeNameAction,
	}
}

// scopePolicy builds one policy for the shared subject, action and scope.
func scopePolicy(id, scope string, effect Effect, recursive bool) Policy {
	return Policy{ID: id, Subject: scopeNameSubjectID, Action: scopeNameAction,
		Scope: scope, Effect: effect, Recursive: recursive}
}

// wantScopeDecision pins the full four-field explanation: verdict, reason,
// exact hit list (order significant; nil and empty both mean "no hits") and
// the version actually evaluated.
func wantScopeDecision(t *testing.T, got Decision, allowed bool, reason string, matched []string, version int, context string) {
	t.Helper()
	if got.Allowed != allowed {
		t.Fatalf("%s: allowed = %v, want %v; decision = %+v", context, got.Allowed, allowed, got)
	}
	if got.Reason != reason {
		t.Fatalf("%s: reason = %q, want %q; decision = %+v", context, got.Reason, reason, got)
	}
	if got.Version != version {
		t.Fatalf("%s: version = %d, want %d; decision = %+v", context, got.Version, version, got)
	}
	gotMatched := got.Matched
	if len(gotMatched) == 0 {
		gotMatched = nil
	}
	wantMatched := matched
	if len(wantMatched) == 0 {
		wantMatched = nil
	}
	if !reflect.DeepEqual(gotMatched, wantMatched) {
		t.Fatalf("%s: matched = %q, want %q; decision = %+v", context, gotMatched, wantMatched, got)
	}
}

// TestExactScopeNameGrantsOnlyTheIdenticalScope is the core isolation guard:
// one exact read allow published on one scope name admits the same-named
// request and no look-alike. Each look-alike is a legal scope (so it reaches
// policy evaluation at the published version) but matches nothing, hence the
// default denial with an empty hit list at version 1 rather than the allow.
func TestExactScopeNameGrantsOnlyTheIdenticalScope(t *testing.T) {
	exact := "org/账本" // Chinese segment name, valid UTF-8
	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-exact-allow", exact, EffectAllow, false),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	// The same-named request hits its own allow and is admitted by it alone.
	same := s.Decide(scopeNameOrg, scopeRequest(exact))
	wantScopeDecision(t, same, true, "matched allow policy",
		[]string{"p-exact-allow"}, 1, "byte-identical scope")

	// Every look-alike is a DIFFERENT scope name: it may not borrow the
	// allow, hits nothing, and falls through to the default denial at the
	// version actually evaluated. None is an invalid request shape.
	lookAlikes := map[string]string{
		"different case in ascii segment": "Org/账本",
		"extra leading space":             " org/账本",
		"extra trailing space":            "org/账本 ",
		"extra space inside the name":     "org/账 本",
		"extra slash-separated space seg": "org/ /账本",
	}
	for name, scope := range lookAlikes {
		d := s.Decide(scopeNameOrg, scopeRequest(scope))
		wantScopeDecision(t, d, false, "no matching allow policy",
			nil, 1, name+" must not match "+showScope(exact))
	}

	// The allow really was available: re-deciding the exact scope after the
	// look-alikes still admits, proving the denials came from name mismatch.
	again := s.Decide(scopeNameOrg, scopeRequest(exact))
	wantScopeDecision(t, again, true, "matched allow policy",
		[]string{"p-exact-allow"}, 1, "exact scope after look-alike probes")
}

// rawByteScopes returns the three byte-different-but-display-conflated scope
// names used by this file. The path shape is identical and exactly one
// segment byte differs: a lone 0xFF, a lone 0xFE, and a genuine U+FFFD code
// point (valid UTF-8, the three bytes EF BF BD).
func rawByteScopes() (withFF, withFE, withReplacement string) {
	return "org/账" + invalidByte + "本",
		"org/账" + anotherInvalidByte + "本",
		"org/账" + replacementRune + "本"
}

// TestRawByteScopeNamesStayDistinct guards the display-confusable triple in
// the scope path: JSON renders the lone 0xFF and lone 0xFE identically, but
// authorization compares raw bytes. With one exact allow on the 0xFF name,
// neither the 0xFE name nor the genuine-U+FFFD name (nor the 0xFF name with
// an extra space) may be admitted; each gets the default denial at the
// evaluated version.
func TestRawByteScopeNamesStayDistinct(t *testing.T) {
	scopeFF, scopeFE, scopeFD := rawByteScopes()

	// Document the premise: Go distinguishes all three, while encoding/json
	// collapses the two lone invalid bytes to one rendering. Any matching
	// layer that normalized before comparing would fail this regression.
	if scopeFF == scopeFE || scopeFF == scopeFD || scopeFE == scopeFD {
		t.Fatalf("test premise broken: scopes must differ pairwise: %q %q %q", scopeFF, scopeFE, scopeFD)
	}
	jFF, _ := json.Marshal(scopeFF)
	jFE, _ := json.Marshal(scopeFE)
	if !bytes.Equal(jFF, jFE) {
		t.Fatalf("test premise broken: JSON renders the invalid bytes differently: %s vs %s", jFF, jFE)
	}

	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-scope-ff-allow", scopeFF, EffectAllow, false),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	allowFF := s.Decide(scopeNameOrg, scopeRequest(scopeFF))
	wantScopeDecision(t, allowFF, true, "matched allow policy",
		[]string{"p-scope-ff-allow"}, 1, "0xFF scope hits its own allow")

	// The look-alikes are legal scopes that match nothing: default denial,
	// empty hit list, but still evaluated at published version 1 — never an
	// envelope rejection and never the 0xFF allow.
	lookAlikes := map[string]string{
		"lone 0xFE look-alike":          scopeFE,
		"genuine U+FFFD look-alike":     scopeFD,
		"0xFF name with a trailing sp.": scopeFF + " ",
		"0xFF name with a leading sp.":  " " + scopeFF,
	}
	for name, scope := range lookAlikes {
		d := s.Decide(scopeNameOrg, scopeRequest(scope))
		wantScopeDecision(t, d, false, "no matching allow policy",
			nil, 1, name)
		for _, hit := range d.Matched {
			if hit == "p-scope-ff-allow" {
				t.Fatalf("%s borrowed the 0xFF allow: %+v", name, d)
			}
		}
	}
}

// TestEachScopeNameHitsOnlyItsOwnPolicy publishes one policy per look-alike
// name in a single version and proves requests cannot cross names. The 0xFF
// name allows, the 0xFE name denies and the genuine-U+FFFD name also allows:
// each request must hit its own identifier and its own effect alone. The
// 0xFE deny in particular must never be reported on either of the other two
// requests.
func TestEachScopeNameHitsOnlyItsOwnPolicy(t *testing.T) {
	scopeFF, scopeFE, scopeFD := rawByteScopes()
	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-scope-ff-allow", scopeFF, EffectAllow, false),
		scopePolicy("p-scope-fe-deny", scopeFE, EffectDeny, false),
		scopePolicy("p-scope-fd-allow", scopeFD, EffectAllow, false),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	dFF := s.Decide(scopeNameOrg, scopeRequest(scopeFF))
	wantScopeDecision(t, dFF, true, "matched allow policy",
		[]string{"p-scope-ff-allow"}, 1, "0xFF scope hits only its own allow")

	dFE := s.Decide(scopeNameOrg, scopeRequest(scopeFE))
	wantScopeDecision(t, dFE, false, "matched deny policy",
		[]string{"p-scope-fe-deny"}, 1, "0xFE scope hits only its own deny")

	dFD := s.Decide(scopeNameOrg, scopeRequest(scopeFD))
	wantScopeDecision(t, dFD, true, "matched allow policy",
		[]string{"p-scope-fd-allow"}, 1, "U+FFFD scope hits only its own allow")

	// A fourth, unlisted but legal name gets the default denial and must not
	// pick up ANY of the three identifiers — especially not the 0xFE deny.
	unlisted := s.Decide(scopeNameOrg, scopeRequest("org/账"+replacementRune+"目"))
	wantScopeDecision(t, unlisted, false, "no matching allow policy",
		nil, 1, "unlisted scope borrows no policy")
}

// TestRecursiveScopeCoversRealDescendantsOnly pins the recursive boundary
// using raw, byte-exact parent names. A recursive allow on "org/a":
//
//   - covers the parent itself and a true child carrying a Chinese segment;
//   - does not cover a same-prefix sibling segment ("org/ab/账本"), since only
//     a real slash starts a child segment;
//   - does not cover "org/a%2F账本": "%2F" is three literal characters in a
//     segment name, never decoded into a slash.
func TestRecursiveScopeCoversRealDescendantsOnly(t *testing.T) {
	parent := "org/a"
	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-rec-allow", parent, EffectAllow, true),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	covered := map[string]string{
		"parent itself":     parent,
		"chinese child":     "org/a/账本",
		"deeper descendant": "org/a/账本/明细",
		"child with spaces": "org/a/账 本 ",
	}
	for name, scope := range covered {
		d := s.Decide(scopeNameOrg, scopeRequest(scope))
		wantScopeDecision(t, d, true, "matched allow policy",
			[]string{"p-rec-allow"}, 1, name)
	}

	notCovered := map[string]string{
		"sibling prefix segment": "org/ab/账本",
		"literal %2F in segment": "org/a%2F账本",
		"percent-encoded deeper": "org/a%2F账本/明细",
		"ancestor":               "org",
		"space-padded lookalike": "org/a /账本",
		"uppercase lookalike":    "org/A/账本",
	}
	for name, scope := range notCovered {
		d := s.Decide(scopeNameOrg, scopeRequest(scope))
		wantScopeDecision(t, d, false, "no matching allow policy",
			nil, 1, name)
	}
}

// TestRecursiveParentWithSpacesOrRawBytesOnlyCoversRawChildren proves the
// descendant prefix is the parent's RAW name plus a slash, even when the
// parent name itself contains spaces or invalid UTF-8 bytes. A child formed
// by appending a slash to a display-alike name is outside the subtree.
func TestRecursiveParentWithSpacesOrRawBytesOnlyCoversRawChildren(t *testing.T) {
	spacedParent := "org/账 本"
	rawParent := "org/账" + invalidByte + "本"

	cases := []struct {
		name    string
		parent  string
		child   string
		outside []string
	}{
		{
			name:   "parent name contains a space",
			parent: spacedParent,
			child:  spacedParent + "/明细",
			outside: []string{
				"org/账/本/明细",                       // space reinterpreted as a slash is not allowed
				"org/账 本x/明细",                      // one extra byte in the segment
				"org/账 本 /明细",                      // trailing space before the separator
				"org/账%20本/明细",                     // literal %20, not the space
				"org/账" + replacementRune + "本/明细", // U+FFFD, not the space
			},
		},
		{
			name:   "parent name contains a lone 0xFF byte",
			parent: rawParent,
			child:  rawParent + "/明细",
			outside: []string{
				"org/账" + anotherInvalidByte + "本/明细", // 0xFE parent prefix
				"org/账" + replacementRune + "本/明细",    // genuine U+FFFD prefix
				"org/账" + invalidByte + "本x/明细",       // longer raw segment
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := NewStore()
			version, err := s.Publish(scopeNameOrg, 0, []Policy{
				scopePolicy("p-rec-raw", tc.parent, EffectAllow, true),
			})
			if err != nil || version != 1 {
				t.Fatalf("publish = %d, %v; want 1, nil", version, err)
			}

			atParent := s.Decide(scopeNameOrg, scopeRequest(tc.parent))
			wantScopeDecision(t, atParent, true, "matched allow policy",
				[]string{"p-rec-raw"}, 1, "read at the raw parent itself")

			child := s.Decide(scopeNameOrg, scopeRequest(tc.child))
			wantScopeDecision(t, child, true, "matched allow policy",
				[]string{"p-rec-raw"}, 1, "child formed by raw parent name plus a slash")

			for _, scope := range tc.outside {
				d := s.Decide(scopeNameOrg, scopeRequest(scope))
				wantScopeDecision(t, d, false, "no matching allow policy",
					nil, 1, "outside subtree: "+showScope(scope))
			}
		})
	}
}

// TestRecursiveDenyBoundaryIsByteExact verifies recursive denies under the
// same name rules. A recursive deny that really covers the request still
// overrides an exact allow on the child, with BOTH identifiers kept in
// ascending order at the evaluated version. But a recursive deny on a
// look-alike parent — org/a rather than org/a%2F账本's true parent, or a
// parent whose name carries 0xFE where the request carries 0xFF — does not
// match and cannot change the other scope's allow.
func TestRecursiveDenyBoundaryIsByteExact(t *testing.T) {
	// Real conflict: recursive deny on org/a covers org/a/账本 even though an
	// exact allow sits on the child.
	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("a-child-allow", "org/a/账本", EffectAllow, false),
		scopePolicy("z-parent-deny", "org/a", EffectDeny, true),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}
	conflict := s.Decide(scopeNameOrg, scopeRequest("org/a/账本"))
	wantScopeDecision(t, conflict, false, "matched deny policy",
		[]string{"a-child-allow", "z-parent-deny"}, 1, "real recursive deny overrides child allow")

	// Submission order must not move the explanation.
	s2 := NewStore()
	if v, err := s2.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("z-parent-deny", "org/a", EffectDeny, true),
		scopePolicy("a-child-allow", "org/a/账本", EffectAllow, false),
	}); err != nil || v != 1 {
		t.Fatalf("reordered publish = %d, %v", v, err)
	}
	reordered := s2.Decide(scopeNameOrg, scopeRequest("org/a/账本"))
	if !reflect.DeepEqual(reordered, conflict) {
		t.Fatalf("policy submission order changed the decision:\n%+v\n%+v", conflict, reordered)
	}

	// Same-prefix miss: the deny on org/a must not reach org/ab/账本. The
	// sibling scope's own exact allow stands alone.
	s3 := NewStore()
	if v, err := s3.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("z-parent-deny", "org/a", EffectDeny, true),
		scopePolicy("ab-exact-allow", "org/ab/账本", EffectAllow, false),
	}); err != nil || v != 1 {
		t.Fatalf("sibling publish = %d, %v", v, err)
	}
	sibling := s3.Decide(scopeNameOrg, scopeRequest("org/ab/账本"))
	wantScopeDecision(t, sibling, true, "matched allow policy",
		[]string{"ab-exact-allow"}, 1, "recursive deny on org/a misses org/ab")

	// Literal-%2F miss: org/a%2F账本 is not under org/a, so its own allow
	// cannot be overridden by the org/a recursive deny.
	s4 := NewStore()
	if v, err := s4.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("z-parent-deny", "org/a", EffectDeny, true),
		scopePolicy("enc-exact-allow", "org/a%2F账本", EffectAllow, false),
	}); err != nil || v != 1 {
		t.Fatalf("encoded publish = %d, %v", v, err)
	}
	encoded := s4.Decide(scopeNameOrg, scopeRequest("org/a%2F账本"))
	wantScopeDecision(t, encoded, true, "matched allow policy",
		[]string{"enc-exact-allow"}, 1, "literal %2F scope is outside org/a's deny subtree")

	// Raw-byte miss: a recursive deny whose parent carries 0xFE must not reach
	// a child of the genuinely-different 0xFF-named parent.
	scopeFF, scopeFE, _ := rawByteScopes()
	s5 := NewStore()
	if v, err := s5.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("rec-deny-fe", scopeFE, EffectDeny, true),
		scopePolicy("child-allow-ff", scopeFF+"/明细", EffectAllow, false),
	}); err != nil || v != 1 {
		t.Fatalf("raw-byte publish = %d, %v", v, err)
	}
	rawChild := s5.Decide(scopeNameOrg, scopeRequest(scopeFF+"/明细"))
	wantScopeDecision(t, rawChild, true, "matched allow policy",
		[]string{"child-allow-ff"}, 1, "0xFE recursive deny misses the 0xFF subtree")
}

// TestConsecutiveSlashScopeRejectedBeforePolicyEvaluation guards the
// legality gate: consecutive slashes make a request scope illegal and the
// request is denied before policy evaluation, with an explicit invalid-scope
// reason, version 0 and an empty hit list. The path must not be tidied and
// then matched against the published allow that covers the normalized form.
func TestConsecutiveSlashScopeRejectedBeforePolicyEvaluation(t *testing.T) {
	s := NewStore()
	// An allow that WOULD cover every normalized form used below, proving the
	// rejection happens before it could be consulted.
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-wide-allow", "org/a", EffectAllow, true),
		scopePolicy("p-ledger-allow", "org/a/账本", EffectAllow, false),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	illegal := []struct {
		name  string
		scope string
	}{
		{"double slash in the middle", "org//a/账本"},
		{"double slash before leaf", "org/a//账本"},
		{"triple slash", "org///a"},
		{"leading slash", "/org/a/账本"},
		{"trailing slash", "org/a/账本/"},
		{"only slashes", "//"},
	}
	for _, tc := range illegal {
		d := s.Decide(scopeNameOrg, scopeRequest(tc.scope))
		if d.Allowed {
			t.Fatalf("%s: request was allowed after tidying: %+v", tc.name, d)
		}
		if d.Version != 0 {
			t.Fatalf("%s: version = %d, want 0 (no published version may be used); decision = %+v",
				tc.name, d.Version, d)
		}
		if len(d.Matched) != 0 {
			t.Fatalf("%s: matched = %q, want no policy hits before evaluation", tc.name, d.Matched)
		}
		if !strings.HasPrefix(d.Reason, "invalid scope") {
			t.Fatalf("%s: reason = %q, want an invalid-scope rejection", tc.name, d.Reason)
		}
		namesConsecutive := strings.Contains(d.Reason, "consecutive slashes")
		namesLeadingTrailing := strings.Contains(d.Reason, "leading or trailing slash")
		if !namesConsecutive && !namesLeadingTrailing {
			t.Fatalf("%s: reason = %q, must name consecutive or leading/trailing slashes", tc.name, d.Reason)
		}
	}

	// The legal form the illegal scopes would have normalized to is genuinely
	// covered, proving the denials above come from the legality gate and not
	// from a missing allow.
	legal := s.Decide(scopeNameOrg, scopeRequest("org/a/账本"))
	wantScopeDecision(t, legal, true, "matched allow policy",
		[]string{"p-ledger-allow", "p-wide-allow"}, 1, "the un-tidied legal scope is covered")
}

// TestInvalidScopePolicyCannotBePublished mirrors the request gate on the
// publishing side: a policy whose scope contains consecutive slashes cannot
// enter any published version, so no later decision can ever match one.
func TestInvalidScopePolicyCannotBePublished(t *testing.T) {
	s := NewStore()
	if v, err := s.Publish(scopeNameOrg, 0, nil); err != nil || v != 1 {
		t.Fatalf("baseline publish = %d, %v", v, err)
	}
	_, err := s.Publish(scopeNameOrg, 1, []Policy{
		scopePolicy("p-bad", "org//a", EffectAllow, false),
	})
	if err == nil {
		t.Fatal("policy with consecutive slashes must fail validation")
	}
	if !errorContains(err, "consecutive slashes") {
		t.Fatalf("err = %v, want it to name consecutive slashes", err)
	}
	if got := s.CurrentVersion(scopeNameOrg); got != 1 {
		t.Fatalf("current version = %d, want 1 after rejected publish", got)
	}
}

// errorContains is a small strings.Contains on err's text kept local so the
// suite does not add an import just for one assertion.
func errorContains(err error, sub string) bool {
	return err != nil && strings.Contains(err.Error(), sub)
}

// TestScopeNameDecisionsSurviveReviewAndAudit pins that the full explanation
// produced by raw-byte scope matching — allow, policy deny and default deny —
// is preserved with reason, hit identifiers and actual version through the
// audit record, historical review, online recheck and offline review. The
// three display-confusable scopes must also stay pairwise distinguishable in
// the signed material rather than collapse onto one replacement character.
func TestScopeNameDecisionsSurviveReviewAndAudit(t *testing.T) {
	scopeFF, scopeFE, scopeFD := rawByteScopes()
	s := NewStore()
	version, err := s.Publish(scopeNameOrg, 0, []Policy{
		scopePolicy("p-scope-ff-allow", scopeFF, EffectAllow, false),
		scopePolicy("p-scope-fe-deny", scopeFE, EffectDeny, true),
		scopePolicy("p-scope-fd-allow", scopeFD, EffectAllow, false),
	})
	if err != nil || version != 1 {
		t.Fatalf("publish = %d, %v; want 1, nil", version, err)
	}

	// Chain layout (seq 1 is the publish), one decision per distinguished
	// outcome:
	//	seq 2  0xFF scope              allow
	//	seq 3  0xFE scope              deny (recursive deny covers itself)
	//	seq 4  genuine U+FFFD scope    allow
	//	seq 5  unlisted raw-byte name  default deny, empty hit list, version 1
	//	seq 6  "org//a" illegal scope  envelope denial, version 0, no hits
	unlistedScope := "org/账" + invalidByte + "目"
	// Decisions must be made in a fixed order: the audit chain assigns its
	// gapless sequence numbers by Decide call order, not by these keys.
	seqScopes := []struct {
		seq   int
		scope string
	}{
		{2, scopeFF}, {3, scopeFE}, {4, scopeFD}, {5, unlistedScope}, {6, "org//a"},
	}
	scopesAtSeq := make(map[int]string, len(seqScopes))
	online := map[int]Decision{}
	for _, item := range seqScopes {
		scopesAtSeq[item.seq] = item.scope
		online[item.seq] = s.Decide(scopeNameOrg, scopeRequest(item.scope))
	}

	wantScopeDecision(t, online[2], true, "matched allow policy",
		[]string{"p-scope-ff-allow"}, 1, "seq 2")
	wantScopeDecision(t, online[3], false, "matched deny policy",
		[]string{"p-scope-fe-deny"}, 1, "seq 3")
	wantScopeDecision(t, online[4], true, "matched allow policy",
		[]string{"p-scope-fd-allow"}, 1, "seq 4")
	wantScopeDecision(t, online[5], false, "no matching allow policy",
		nil, 1, "seq 5 default deny keeps version 1")
	if d6 := online[6]; d6.Allowed || d6.Version != 0 || len(d6.Matched) != 0 ||
		!strings.HasPrefix(d6.Reason, "invalid scope") {
		t.Fatalf("seq 6 illegal scope = %+v, want version-0 invalid-scope denial with no hits", d6)
	}

	recs, cp, err := s.AuditExport(scopeNameOrg, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(recs) != 6 {
		t.Fatalf("chain length = %d, want 6 (one publish + five decisions)", len(recs))
	}
	if err := VerifyAudit(scopeNameOrg, recs, cp); err != nil {
		t.Fatalf("raw-byte scope chain must verify: %v", err)
	}

	// Each record stores the submitted scope bytes and the returned decision
	// in full; distinct scope names must not collapse in signed material.
	for seq, wantScope := range scopesAtSeq {
		r := recs[seq-1]
		if r.Kind != AuditDecision || r.Decision == nil {
			t.Fatalf("seq %d is not a decision record: %+v", seq, r)
		}
		if r.Decision.Request.Resource.Scope != wantScope {
			t.Fatalf("seq %d stored scope %q, want byte-exact %q", seq,
				r.Decision.Request.Resource.Scope, wantScope)
		}
		if !reflect.DeepEqual(r.Decision.Decision, online[seq]) {
			t.Fatalf("seq %d stored decision %+v != returned %+v",
				seq, r.Decision.Decision, online[seq])
		}
	}
	fps := map[string]int{}
	for _, seq := range []int{2, 3, 4} {
		fp := recs[seq-1].Fingerprint
		if other, dup := fps[fp]; dup {
			t.Fatalf("seqs %d and %d share fingerprint %s: confusable scopes collapsed", other, seq, fp)
		}
		fps[fp] = seq
	}

	// Historical review against version 1 reproduces every explanation, and
	// review of the illegal scope still rejects at the envelope with
	// version 0 and no hits — review never tidies before evaluating either.
	for seq, wantScope := range scopesAtSeq {
		reviewed := s.Review(scopeNameOrg, version, scopeRequest(wantScope))
		if !reflect.DeepEqual(reviewed, online[seq]) {
			t.Fatalf("seq %d (scope %q) review %+v != online %+v",
				seq, wantScope, reviewed, online[seq])
		}
	}

	// Online recheck replays from the recorded material, including the
	// default deny (version 1, empty hit list) and the envelope denial.
	for seq := range scopesAtSeq {
		replayed, err := s.RecheckDecision(scopeNameOrg, seq)
		if err != nil {
			t.Fatalf("RecheckDecision seq %d: %v", seq, err)
		}
		if !reflect.DeepEqual(replayed, online[seq]) {
			t.Fatalf("seq %d recheck %+v != recorded %+v", seq, replayed, online[seq])
		}
	}

	// Offline review over the chain-validated export recomputes each decision
	// from the saved raw scope and the recorded version, marked consistent.
	for seq := range scopesAtSeq {
		review, err := RecheckDecisionOffline(scopeNameOrg, recs, cp, seq)
		if err != nil {
			t.Fatalf("offline review seq %d: %v", seq, err)
		}
		if !review.Consistent {
			t.Fatalf("seq %d offline review inconsistent: original %+v vs recomputed %+v",
				seq, review.Original, review.Recomputed)
		}
		if !reflect.DeepEqual(review.Recomputed, online[seq]) {
			t.Fatalf("seq %d recomputed %+v != online %+v",
				seq, review.Recomputed, online[seq])
		}
	}
}

// showScope renders a scope for failure messages without relying on its
// displayed form, since the confusable bytes all render alike.
func showScope(scope string) string {
	return strings.ReplaceAll(strings.ReplaceAll(scope, invalidByte, `<FF>`), anotherInvalidByte, `<FE>`)
}

// This file holds the shared core of single-decision review. The online
// Store.RecheckDecision and the store-free RecheckDecisionOffline acquire
// their material differently — one reads an organization's live history
// and version snapshots, the other a chain-validated export paired with its
// separately retained checkpoint — but once the recorded request and the
// version it actually used are in hand, both replay the exact same
// judgment. That judgment lives only here so the two entry points can never
// drift on version-zero handling, envelope rejection order, or how a
// historical policy set is evaluated.
package darksafe

// replayStatus reports whether replayRecordedDecision produced a decision
// or why the declared version could not be replayed.
type replayStatus int

const (
	// replayDecided means a Decision was recomputed.
	replayDecided replayStatus = iota
	// replayVersionAbsent means content for the declared version exists
	// nowhere in the reviewer's material.
	replayVersionAbsent
	// replayVersionAfterTarget means the version's content exists, but only
	// in a policy change record positioned after the reviewed decision.
	// Online material never yields this: live version snapshots carry no
	// position relative to audit records.
	replayVersionAfterTarget
)

// versionPolicies is one resolver verdict: either the detached full policy
// set of the requested version, or a status explaining why it is unusable.
type versionPolicies struct {
	policies []Policy
	status   replayStatus
}

// resolveVersionPolicies supplies the full content of a non-zero version
// named by a reviewed decision. Implementations are responsible for
// detaching the returned policies from any state or input material.
type resolveVersionPolicies func(version int) versionPolicies

// replayRecordedDecision re-judges a recorded request against the version
// the record declares it actually used. Later publishes or rollbacks are
// never substituted for that version.
//
// A version-0 record first replays the envelope rejections in their fixed
// order (missing organizations and identifiers, empty action, organization
// mismatch, illegal scope, disabled subject); a request that passes is the
// "organization has no published version" denial.
//
// For a non-zero record the version is resolved before any request rule is
// applied: a missing, or only-later, version is an error the caller turns
// into ErrVersionNotFound and must never be masked by an envelope denial,
// even for a disabled subject. Once the version is in hand, the same
// envelope checks run before policy evaluation, so a rejection reports
// version 0 with no matched policies regardless of what the version
// contains. Evaluation itself is the historical policy set only: deny
// overrides allow, matched identifiers are sorted, resource restrictions
// narrow rather than replace scope matching, and subject roles never stand
// in for an organization policy.
func replayRecordedDecision(org string, req OrgRequest, version int, resolve resolveVersionPolicies) (Decision, replayStatus) {
	if version == 0 {
		// The original evaluation used no published version: replay the
		// envelope rejections exactly, in their recorded order, then the
		// not-yet-published denial.
		if d, ok := checkRequest(org, req); !ok {
			return d, replayDecided
		}
		return Decision{Allowed: false, Reason: "organization has no published version"}, replayDecided
	}
	// Resolve the version first. A request the envelope would reject must
	// not turn a missing or later-only declared version into an ordinary
	// denial.
	resolved := resolve(version)
	if resolved.status != replayDecided {
		return Decision{}, resolved.status
	}
	// The version exists as claimed, but chain integrity does not imply the
	// request was admissible: re-run the same envelope checks the online
	// decision runs before any policy is consulted. A rejection here
	// evaluates no policies, hence version 0 and no matches, even when the
	// version holds a fully matching allow policy.
	if d, ok := checkRequest(org, req); !ok {
		return d, replayDecided
	}
	return evaluate(req, resolved.policies, version), replayDecided
}

package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"
)

// invalidByte is a lone byte that is never valid UTF-8 on its own.
const invalidByte = "\xff"

// anotherInvalidByte renders identically under JSON replacement but is a
// different raw byte.
const anotherInvalidByte = "\xfe"

// replacementRune is a genuine U+FFFD code point: valid UTF-8, unlike the
// lone invalid bytes.
const replacementRune = string(rune(0xFFFD))

// hashEnvelope is the historical fingerprint envelope struct the legacy
// JSON fingerprint family was computed over. Production no longer names
// it — the single record field table (record_fields.go) defines the
// envelope now — but the tests keep it as an independent oracle: if the
// table-driven JSON encoder ever drifted from the historical
// encoding/json output, the comparisons against legacyJSONFingerprint
// would catch it.
type hashEnvelope struct {
	Org             string          `json:"org"`
	Seq             int             `json:"seq"`
	Kind            string          `json:"kind"`
	Change          *PolicyChange   `json:"change,omitempty"`
	Decision        *DecisionRecord `json:"decision,omitempty"`
	PrevFingerprint string          `json:"prev"`
}

