package darksafe

import (
	"errors"
	"fmt"
	"reflect"
	"sync"
	"sync/atomic"
	"testing"
)

// drainAudit collects every record of an organization using the public
// pinned-query API.
func drainAudit(t *testing.T, s *Store, org, kind, subject string) []AuditRecord {
	t.Helper()
	page, err := s.AuditQuery(org, 1, 4, kind, subject)
	if err != nil {
		t.Fatalf("AuditQuery: %v", err)
	}
	var out []AuditRecord
	for {
		out = append(out, page.Records...)
		if page.Next == 0 {
			break
		}
		page, err = s.AuditPage(page.Checkpoint, page.Next, 4, kind, subject)
		if err != nil {
			t.Fatalf("AuditPage: %v", err)
		}
	}
	return out
}

func TestPublishLeavesPolicyChangeRecord(t *testing.T) {
	s := NewStore()
	policies := []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}
	v, err := s.Publish("acme", 0, policies)
	if err != nil {
		t.Fatal(err)
	}
	recs := drainAudit(t, s, "acme", "", "")
	if len(recs) != 1 {
		t.Fatalf("records = %d, want 1", len(recs))
	}
	r := recs[0]
	if r.Org != "acme" || r.Seq != 1 || r.Kind != AuditPolicyChange {
		t.Fatalf("bad record header: %+v", r)
	}
	if r.Change == nil || r.Change.Version != v || r.Change.RolledBack || r.Change.SourceVersion != 0 {
		t.Fatalf("bad change payload: %+v", r.Change)
	}
	if !reflect.DeepEqual(r.Change.Policies, policies) {
		t.Fatalf("stored policies = %+v, want %+v", r.Change.Policies, policies)
	}
	if r.PrevFingerprint == "" || r.Fingerprint == "" || r.PrevFingerprint == r.Fingerprint {
		t.Fatalf("fingerprints not populated: %+v", r)
	}
}

func TestRollbackRecordNamesSourceVersion(t *testing.T) {
	s := NewStore()
	v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
	if _, err := s.Publish("acme", v1, nil); err != nil {
		t.Fatal(err)
	}
	v3, err := s.Rollback("acme", 2, v1)
	if err != nil {
		t.Fatal(err)
	}
	recs := drainAudit(t, s, "acme", AuditPolicyChange, "")
	if len(recs) != 3 {
		t.Fatalf("change records = %d, want 3", len(recs))
	}
	rb := recs[2]
	if !rb.Change.RolledBack || rb.Change.SourceVersion != v1 || rb.Change.Version != v3 {
		t.Fatalf("rollback payload = %+v", rb.Change)
	}
	if len(rb.Change.Policies) != 1 || rb.Change.Policies[0].ID != "p1" {
		t.Fatalf("rollback must carry full new content: %+v", rb.Change.Policies)
	}
}

func TestFailedPublishAndRollbackLeaveNoRecord(t *testing.T) {
	s := NewStore()
	v1, _ := s.Publish("acme", 0, nil)
	if _, err := s.Publish("acme", v1, []Policy{{ID: "", Effect: EffectAllow}}); !errors.Is(err, ErrInvalidPolicySet) {
		t.Fatalf("invalid publish err = %v", err)
	}
	if _, err := s.Publish("acme", 0, nil); !errors.Is(err, ErrVersionConflict) {
		t.Fatalf("stale publish err = %v", err)
	}
	if _, err := s.Rollback("acme", v1, 99); !errors.Is(err, ErrVersionNotFound) {
		t.Fatalf("bad rollback err = %v", err)
	}
	if _, err := s.Rollback("acme", 0, v1); !errors.Is(err, ErrVersionConflict) {
		t.Fatalf("stale rollback err = %v", err)
	}
	recs := drainAudit(t, s, "acme", "", "")
	if len(recs) != 1 || recs[0].Change.Version != 1 {
		t.Fatalf("records after failures = %+v, want only version 1", recs)
	}
}

func TestDecideRecordsEveryOutcome(t *testing.T) {
	s := NewStore()
	// No published version yet: the denial is still recorded.
	d0 := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	if d0.Allowed || d0.Version != 0 {
		t.Fatalf("unexpected decision %+v", d0)
	}
	if _, err := s.Publish("acme", 0, []Policy{
		allowPolicy("p-allow", "u1", "read", "org/a", false),
		{ID: "p-deny", Subject: "u2", Action: "read", Scope: "org/a", Effect: EffectDeny},
	}); err != nil {
		t.Fatal(err)
	}
	allow := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	deny := s.Decide("acme", request("acme", "u2", "r1", "org/a", "read"))
	noMatch := s.Decide("acme", request("acme", "u9", "r1", "org/a", "read"))
	disabled := request("acme", "u1", "r1", "org/a", "read")
	disabled.Subject.Disabled = true
	ddis := s.Decide("acme", disabled)
	mismatch := request("acme", "u1", "r1", "org/a", "read")
	mismatch.SubjectOrg = "globex"
	dmis := s.Decide("acme", mismatch)
	missing := request("acme", "u1", "r1", "org/a", "read")
	missing.Resource.ID = ""
	dmiss := s.Decide("acme", missing)

	recs := drainAudit(t, s, "acme", AuditDecision, "")
	want := []Decision{d0, allow, deny, noMatch, ddis, dmis, dmiss}
	if len(recs) != len(want) {
		t.Fatalf("decision records = %d, want %d", len(recs), len(want))
	}
	for i, r := range recs {
		if r.Kind != AuditDecision || r.Decision == nil {
			t.Fatalf("record %d not a decision: %+v", i, r)
		}
		if !reflect.DeepEqual(r.Decision.Decision, want[i]) {
			t.Fatalf("record %d decision = %+v, want %+v", i, r.Decision.Decision, want[i])
		}
	}
	// The full request is preserved, including the envelope rejection cases.
	if recs[4].Decision.Request.Subject.ID != "u1" || !recs[4].Decision.Request.Subject.Disabled {
		t.Fatalf("disabled request not stored: %+v", recs[4].Decision.Request)
	}
	if recs[5].Decision.Request.SubjectOrg != "globex" {
		t.Fatalf("mismatched org request not stored: %+v", recs[5].Decision.Request)
	}
	// Sequences ascend and match the underlying chain positions (the
	// publish sits at seq 2 and is filtered out of this view).
	wantSeqs := []int{1, 3, 4, 5, 6, 7, 8}
	gotSeqs := make([]int, len(recs))
	for i, r := range recs {
		gotSeqs[i] = r.Seq
	}
	if !reflect.DeepEqual(gotSeqs, wantSeqs) {
		t.Fatalf("decision seqs = %v, want %v", gotSeqs, wantSeqs)
	}
}

func TestDecideMissingOrgLeavesNoRecordAnywhere(t *testing.T) {
	s := NewStore()
	d := s.Decide("", request("acme", "u1", "r1", "org/a", "read"))
	if d.Allowed || d.Reason != "missing decision organization" {
		t.Fatalf("missing-org decision = %+v", d)
	}
	if _, _, err := s.AuditExport("", 0); !errors.Is(err, ErrMissingOrganization) {
		t.Fatalf("export without org err = %v", err)
	}
	if _, err := s.AuditQuery("", 1, 1, "", ""); !errors.Is(err, ErrMissingOrganization) {
		t.Fatalf("query without org err = %v", err)
	}
	if _, err := s.RecheckDecision("", 1); !errors.Is(err, ErrMissingOrganization) {
		t.Fatalf("recheck without org err = %v", err)
	}
	if _, err := s.AuditPage(Checkpoint{}, 1, 1, "", ""); !errors.Is(err, ErrMissingOrganization) {
		t.Fatalf("page without org err = %v", err)
	}
}

// Command org_decision_example shows why one subject gets different answers
// from the role-based demo core (Access) and the organization-level policy
// engine (Store.Decide): the two are separate authorization bases. Access
// trusts the subject's roles; Decide ignores roles entirely and evaluates
// only the decision organization's published policies.
//
// Run with:
//
//	go run ./examples/org_decision
//
// The program takes no arguments, writes no files, and works fully offline.
// One subject carrying the owner role reads one ledger:
//
//  1. Access allows it, because the owner role is enough for the demo core.
//  2. A fresh Store denies the same read, because the organization has not
//     published any policy yet (version 0: no published policy was used).
//  3. After publishing one matching allow policy, the identical request is
//     allowed and reports the policy it matched and the version it used.
//  4. Two envelope boundaries deny before any policy is consulted: a
//     disabled subject, and a subject/resource organization that differs
//     from the decision organization. Both report version 0 and no matches.
package main

import (
	"fmt"
	"os"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "org decision example: failed:", err)
		os.Exit(1)
	}
}

func run() error {
	// One organization, one ledger, one subject. The subject carries the
	// owner role, which is decisive for Access and meaningless for Decide.
	const org = "acme factory"
	const (
		ledgerID    = "ledger-2026"
		ledgerScope = "acme/factory/ledger"
		subjectID   = "svc-audit-reader"
	)
	subject := darksafe.Subject{ID: subjectID, Kind: "service", Roles: []string{"owner"}}
	ledger := darksafe.Resource{ID: ledgerID, Scope: ledgerScope}

	// 1. The demo entry point's basis: roles. owner grants the read.
	printDecision("access  (role owner, no policy store)", darksafe.Access(subject, ledger, "read"))

	// 2. The organization-level basis: published policies. The request
	// envelope is valid (all three organizations agree, the scope is legal),
	// but nothing has been published, so the default is denial and the
	// version is 0 — no published policy was evaluated.
	store := darksafe.NewStore()
	req := darksafe.OrgRequest{
		SubjectOrg:  org,
		ResourceOrg: org,
		Subject:     subject,
		Resource:    ledger,
		Action:      "read",
	}
	printDecision("decide  (no published policy)      ", store.Decide(org, req))

	// 3. Publish one allow policy matching this subject, the read action and
	// the ledger scope, then submit the identical request again.
	version, err := store.Publish(org, 0, []darksafe.Policy{{
		ID:      "p-ledger-read-2026",
		Subject: subjectID,
		Action:  "read",
		Scope:   ledgerScope,
		Effect:  darksafe.EffectAllow,
	}})
	if err != nil {
		return fmt.Errorf("publish allow policy: %w", err)
	}
	fmt.Printf("published allow policy p-ledger-read-2026 as version %d\n", version)
	printDecision("decide  (allow policy published)   ", store.Decide(org, req))

	// Boundary 1: the same subject disabled. The matching allow policy is
	// still published, but the envelope check rejects first — no policy is
	// evaluated, so the version is 0 and the matched list is empty.
	disabled := req
	disabled.Subject.Disabled = true
	printDecision("decide  (subject disabled)         ", store.Decide(org, disabled))

	// Boundary 2: the subject's organization differs from the decision
	// organization (a resource-organization mismatch denies the same way).
	// Again no policy is evaluated: version 0, no matches.
	cross := req
	cross.SubjectOrg = "other org"
	printDecision("decide  (subject org mismatch)     ", store.Decide(org, cross))
	return nil
}

// printDecision prints the four fields both authorization bases report:
// allowed or not, the reason, the matched list (roles for Access, policy
// IDs for Decide) and the policy version actually used (0 when none was).
func printDecision(label string, d darksafe.Decision) {
	fmt.Printf("%s: allowed=%v reason=%q matched=%q version=%d\n",
		label, d.Allowed, d.Reason, d.Matched, d.Version)
}

// This file implements offline review of a single audited decision. It
// works solely from exported audit material: the complete record export,
// the separately retained checkpoint, and a target sequence. No Store is
// created or restored, so an organization can confirm why an access was
// allowed or denied long after the service instance that decided it has
// ended.
//
// The complete input must first validate as an audit chain. The policy
// version a decision actually used is recovered exclusively from policy
// change records preceding that decision within the same organization's
// export; later publishes or rollbacks, and a wider later export, cannot
// change the recomputed result.
//
// A review that already holds the material as decoded records
// (RecheckDecisionOffline) and one that starts from an archive file
// (DecodeAuditArchive followed by a review) historically each ran the full
// VerifyAudit chain check on their own, so `darksafe review` validated the
// same material twice per invocation. The two stages now share one pass:
// VerifyAudit runs exactly once per review, its result is carried in an
// unexported VerifiedAuditMaterial, and the review replays the target from
// that already-verified material without re-checking the chain. The
// standalone entry points keep validating their own inputs, so neither
// requires the caller to have run another entry point first.
package darksafe

import "fmt"

// OfflineDecisionReview compares the decision stored in an audited record
// with a decision recomputed purely from the exported material.
type OfflineDecisionReview struct {
	// Seq is the reviewed decision record's sequence.
	Seq int
	// Original is the decision preserved in the audited record.
	Original Decision
	// Recomputed is the decision evaluated again offline from the saved
	// request and the policy version it originally used.
	Recomputed Decision
	// Consistent reports whether both decisions agree on every field
	// (allowance, reason, matched policies and version), treating a nil
	// matched list and an empty matched list as the same.
	Consistent bool
}

// VerifiedAuditMaterial is an export that has passed the complete
// VerifyAudit chain check against the checkpoint it carries. It is the
// boundary between one validation and the review: an entry point that has
// just validated the material hands it to RecheckVerifiedDecisionOffline,
// and the review replays the target without validating the chain a second
// time.
//
// It is intentionally unexported: it can only be produced by this package's
// own validating entry points (verifyAuditMaterial, reached from
// RecheckDecisionOffline, DecodeAuditArchive and DecodeVerifiedAuditArchive),
// never from a caller's assertion. It carries no memo that survives the
// call that produced it, so modified material or a different checkpoint
// always forces a fresh validation; the embedded records are the caller's
// and stay owned by the caller.
type VerifiedAuditMaterial struct {
	org     string
	records []AuditRecord
	cp      Checkpoint
}

// verifyAuditMaterial validates the whole export exactly as VerifyAudit
// does and, on success, returns it as VerifiedAuditMaterial. It is the
// single place the chain check is performed on the offline review path; a
// failure returns no material, so a later stage can never review records
// that did not validate.
func verifyAuditMaterial(org string, records []AuditRecord, cp Checkpoint) (VerifiedAuditMaterial, error) {
	if verifyAuditObserver != nil {
		verifyAuditObserver()
	}
	if err := VerifyAudit(org, records, cp); err != nil {
		return VerifiedAuditMaterial{}, err
	}
	return VerifiedAuditMaterial{org: org, records: records, cp: cp}, nil
}

// RecheckVerifiedDecisionOffline re-evaluates one decision record from
// material a preceding stage has already chain-validated as one unit
// (verifyAuditMaterial or DecodeVerifiedAuditArchive). It does not run the
// chain check again: one review performs one complete chain validation, and
// tampering anywhere is rejected before this stage is reached. All target
// and replay guarantees are otherwise identical to
// RecheckDecisionOffline's: ErrAuditNotFound for a non-positive or absent
// target sequence, ErrAuditNotADecision when the target is a policy change
// record, and ErrVersionNotFound when the version the decision names has no
// change record before the target (including content that appears only
// after it); a newer version is never substituted. The call is read-only
// and the returned decisions are detached from the material's slices.
func RecheckVerifiedDecisionOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	return recheckVerifiedOffline(m, seq)
}

// recheckVerifiedOffline is the shared review body. It takes an unexported
// verified-material value so only this package's validating stages can
// reach the already-validated path; standalone RecheckDecisionOffline
// validates first and then calls it just as the combined archive flow does.
func recheckVerifiedOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	org, records := m.org, m.records
	if seq < 1 {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	if seq > len(records) {
		return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
	}
	rec := &records[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}

	original := cloneDecisionValue(rec.Decision.Decision)
	req := rec.Decision.Request
	// Detach the request list by non-nil rather than by length: a non-nil
	// empty role list with spare capacity must not be shared back with the
	// caller's material, even though evaluation never reads any element.
	req.Subject.Roles = cloneStrings(req.Subject.Roles)
	version := original.Version

	// The version's full content must travel in a same-organization policy

// This file is the single definition of which fields a DecisionRecord
// carries for every audit-side treatment of decision content: the
// fingerprint's raw canonical encoder, the valid-UTF-8 test that chooses
// between the JSON and raw fingerprint families, the archive writer and
// reader, and the detaching copy that keeps stored records independent of
// caller slices. Each of those walks the one table below instead of naming
// the fields itself, so the fields and their order mean the same thing
// everywhere. Adding or changing a decision field here reaches
// fingerprinting, the UTF-8 decision, archiving, unarchiving and cloning at
// once; no audit path can keep a stale list of its own.
//
// The table order is part of the wire and fingerprint contract: it is the
// historical decision field order — the two organization names, the subject,
// the resource, the action, then the decision itself — and the archive
// mirrors it field for field. Authorization itself (org.go) is intentionally
// not driven from this table: Roles participates here as a saved request
// field even though org policy evaluation never matches on it.
package darksafe

import "unicode/utf8"

// decisionFieldKind says how one DecisionRecord field participates in
// fingerprinting and archiving.
type decisionFieldKind int

const (
	// decisionFieldString is a string field written from its exact bytes by
	// both the fingerprint encoder and the archive.
	decisionFieldString decisionFieldKind = iota
	// decisionFieldStringList is a string slice whose nil-versus-empty
	// shape and element order are preserved explicitly by both encoders.
	decisionFieldStringList
	// decisionFieldBool is a boolean field. It has no UTF-8 representation,
	// so the valid-UTF-8 scan skips it while both encoders write it.
	decisionFieldBool
	// decisionFieldInt is a non-negative integer field (the policy version
	// the decision used). It has no UTF-8 representation either.
	decisionFieldInt
)

// decisionFieldSpec locates one DecisionRecord leaf field. The accessors
// used depend on the kind: string fields use getString/setString, list
// fields getList/setList, booleans getBool/setBool and integers
// getInt/setInt. A field appears in decisionFields exactly once, and that
// entry is the only place its struct member is named.
type decisionFieldSpec struct {
	kind decisionFieldKind
	// groupTag, when non-zero, is a nesting marker the fingerprint encoder
	// emits immediately before this field, opening the subject, resource or
	// decision group exactly where the historical encoding placed it. The
	// archive has no group markers and ignores this.
	groupTag  fingerprintTag
	getString func(*DecisionRecord) string
	setString func(*DecisionRecord, string)
	getList   func(*DecisionRecord) []string
	setList   func(*DecisionRecord, []string)
	getBool   func(*DecisionRecord) bool
	setBool   func(*DecisionRecord, bool)
	getInt    func(*DecisionRecord) int
	setInt    func(*DecisionRecord, int)
}

// decisionFields lists every DecisionRecord leaf field in fingerprint
// canonical order, which the archive reproduces exactly. The subject group
// opens at Subject.ID, the resource group at Resource.ID and the decision
// group at Decision.Allowed, matching the historical nesting markers.
var decisionFields = [...]decisionFieldSpec{
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.SubjectOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.SubjectOrg = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.ResourceOrg },
		setString: func(d *DecisionRecord, s string) { d.Request.ResourceOrg = s },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagSubject,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Subject.Kind },
		setString: func(d *DecisionRecord, s string) { d.Request.Subject.Kind = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Request.Subject.Roles },
		setList: func(d *DecisionRecord, l []string) { d.Request.Subject.Roles = l },
	},
	{
		kind:    decisionFieldBool,
		getBool: func(d *DecisionRecord) bool { return d.Request.Subject.Disabled },
		setBool: func(d *DecisionRecord, v bool) { d.Request.Subject.Disabled = v },
	},
	{
		kind:      decisionFieldString,
		groupTag:  tagResource,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.ID },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.ID = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Resource.Scope },
		setString: func(d *DecisionRecord, s string) { d.Request.Resource.Scope = s },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Request.Action },
		setString: func(d *DecisionRecord, s string) { d.Request.Action = s },
	},
	{
		kind:     decisionFieldBool,
		groupTag: tagDecision,
		getBool:  func(d *DecisionRecord) bool { return d.Decision.Allowed },
		setBool:  func(d *DecisionRecord, v bool) { d.Decision.Allowed = v },
	},
	{
		kind:      decisionFieldString,
		getString: func(d *DecisionRecord) string { return d.Decision.Reason },
		setString: func(d *DecisionRecord, s string) { d.Decision.Reason = s },
	},
	{
		kind:    decisionFieldStringList,
		getList: func(d *DecisionRecord) []string { return d.Decision.Matched },
		setList: func(d *DecisionRecord, l []string) { d.Decision.Matched = l },
	},
	{
		kind:   decisionFieldInt,
		getInt: func(d *DecisionRecord) int { return d.Decision.Version },
		setInt: func(d *DecisionRecord, v int) { d.Decision.Version = v },
	},
}

// decisionRecordHasNonUTF8 reports whether any string or list element of d
// carries bytes that are not valid UTF-8. It ranges the single field table,
// so its idea of which decision strings the fingerprint protects can never
// diverge from the fields the encoders write. Boolean and integer fields
// cannot carry a raw byte and are skipped by kind rather than listed
// separately.
func decisionRecordHasNonUTF8(d *DecisionRecord) bool {
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			if !utf8.ValidString(f.getString(d)) {
				return true
			}
		case decisionFieldStringList:
			for _, s := range f.getList(d) {
				if !utf8.ValidString(s) {
					return true
				}
			}
		}
	}
	return false
}

// cloneDecisionLists detaches every string list field of src into dst,
// preserving each list's nil-versus-empty shape. It ranges the single field
// table, so a list field added to the record is detached here without this
// function changing.
func cloneDecisionLists(dst, src *DecisionRecord) {
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.kind == decisionFieldStringList {
			f.setList(dst, cloneStrings(f.getList(src)))
		}
	}
}

